/*
 * Entry-gate server service (DESIGN-PRODUCTION.md §2.4, Phase 6).
 *
 * The client gate machine (gateMachine.ts) owns presentation; THIS
 * service owns the server record (M1, roamly_gate_states) and the
 * enforcement decision. The split follows the design's core rule: the
 * evidence for gate events is generated by real platform state, never
 * accepted from a caller's assertion.
 *
 * What "evidence" means here, honestly (device-attested state, not a
 * security proof):
 *  - Install: the client reports the display-mode reading
 *    (standalone / navigator.standalone) from the installed context.
 *    A self-report ("I've installed it") is not an input to this
 *    service at all.
 *  - Alerts: the client reports Notification.permission as read, AND
 *    the server independently verifies a live push subscription for
 *    this user in roamly_push_subscriptions — a granted claim with no
 *    subscription on file does NOT turn the record green.
 *  - flowAllowed is computed HERE and persisted; the Phase 1 parser
 *    (parseGateStateDTO) refuses any READY record that lacks the
 *    detected install or the granted alerts, so a green record cannot
 *    be written by accident or by a forged request.
 *
 * Gmail gate state is derived from the existing email_connections
 * table (the source of truth — Phase 6 builds no parallel store):
 * consent scope is the scope recorded at connection time, and
 * RECONCILIATION_ARMED additionally requires the recorded Build 2
 * consent label in the gate row, written when the connection is first
 * observed (consent is recorded BEFORE the first Gmail read — the
 * connection row itself is written by the OAuth callback before any
 * sync runs).
 */

import type { SupabaseClient } from "@supabase/supabase-js";
import {
  parseGateStateDTO,
  type GateStateDTO,
  type GmailGateState,
  type InstallGateState
} from "@/lib/roamly/engine/types";
import type { UtcInstant } from "@/lib/roamly/engine/time";
import { build2GatesEnabled } from "@/lib/roamly/build2Flags";
import {
  ALERTS_BLOCK_MESSAGE,
  GMAIL_CONSENT_SCOPE,
  INSTALL_BLOCK_MESSAGE
} from "@/lib/roamly/gateMachine";
import { GMAIL_PROVIDER, GMAIL_READONLY_SCOPE } from "@/lib/roamly/emailConnections";

export const GATE_STATES_TABLE = "roamly_gate_states";

/* ------------------------------------------------------------------ */
/* Store seam                                                          */
/* ------------------------------------------------------------------ */

export interface GateStore {
  load(userId: string, deviceId: string): Promise<GateStateDTO | null>;
  save(record: GateStateDTO): Promise<void>;
  /** Server-side proof for the alerts leg: a live push subscription. */
  hasPushSubscription(userId: string, endpoint?: string | null): Promise<boolean>;
}

interface GateStateRow {
  user_id: string;
  device_id: string;
  platform: string;
  install_state: string;
  install_detected_at: string | null;
  alerts_permission: string | null;
  alerts_checked_at: string | null;
  gmail_state: string;
  gmail_connection_id: string | null;
  gmail_consent_scope: string | null;
  flow_allowed: boolean;
  updated_at: string;
}

function rowToDTO(row: GateStateRow): GateStateDTO {
  return {
    userId: row.user_id,
    deviceId: row.device_id,
    platform: row.platform === "ios" || row.platform === "android" ? row.platform : "other",
    installState: row.install_state as InstallGateState,
    alertsPermission:
      row.alerts_permission === "granted" || row.alerts_permission === "denied" || row.alerts_permission === "default"
        ? row.alerts_permission
        : null,
    alertsCheckedAt: row.alerts_checked_at as UtcInstant | null,
    installDetectedAt: row.install_detected_at as UtcInstant | null,
    gmailState: row.gmail_state as GmailGateState,
    gmailConnectionRef: row.gmail_connection_id,
    gmailConsentScope: row.gmail_consent_scope,
    flowAllowed: row.flow_allowed === true,
    updatedAt: row.updated_at as UtcInstant
  };
}

function dtoToRow(record: GateStateDTO): Record<string, unknown> {
  return {
    user_id: record.userId,
    device_id: record.deviceId,
    platform: record.platform,
    install_state: record.installState,
    install_detected_at: record.installDetectedAt,
    alerts_permission: record.alertsPermission,
    alerts_checked_at: record.alertsCheckedAt,
    gmail_state: record.gmailState,
    gmail_connection_id: record.gmailConnectionRef,
    gmail_consent_scope: record.gmailConsentScope,
    flow_allowed: record.flowAllowed,
    updated_at: record.updatedAt
  };
}

export function createSupabaseGateStore(supabase: SupabaseClient): GateStore {
  return {
    async load(userId, deviceId) {
      const { data, error } = await supabase
        .from(GATE_STATES_TABLE)
        .select(
          "user_id, device_id, platform, install_state, install_detected_at, alerts_permission, alerts_checked_at, gmail_state, gmail_connection_id, gmail_consent_scope, flow_allowed, updated_at"
        )
        .eq("user_id", userId)
        .eq("device_id", deviceId)
        .maybeSingle();
      if (error) {
        // A missing M1 table reads as "no record" — enforcement then
        // refuses closed, which is the law (no attestation, no pass).
        if (error.code === "42P01" || /relation .* does not exist/i.test(error.message || "")) return null;
        throw new Error(`gate state load failed: ${error.message}`);
      }
      return data ? rowToDTO(data as GateStateRow) : null;
    },

    async save(record) {
      const { error } = await supabase
        .from(GATE_STATES_TABLE)
        .upsert(dtoToRow(record), { onConflict: "user_id,device_id" });
      if (error) throw new Error(`gate state save failed: ${error.message}`);
    },

    async hasPushSubscription(userId, endpoint) {
      let query = supabase
        .from("roamly_push_subscriptions")
        .select("id")
        .eq("user_id", userId)
        .eq("enabled", true)
        .limit(1);
      if (endpoint) query = query.eq("endpoint", endpoint);
      const { data, error } = await query;
      if (error) throw new Error(`push subscription lookup failed: ${error.message}`);
      return Array.isArray(data) && data.length > 0;
    }
  };
}

/** Deterministic in-memory store for the check harness. */
export class InMemoryGateStore implements GateStore {
  private readonly records = new Map<string, GateStateDTO>();
  private readonly subscriptions = new Set<string>();

  seedSubscription(userId: string, endpoint?: string): void {
    this.subscriptions.add(endpoint ? `${userId}|${endpoint}` : userId);
  }

  async load(userId: string, deviceId: string): Promise<GateStateDTO | null> {
    return this.records.get(`${userId}|${deviceId}`) ?? null;
  }

  async save(record: GateStateDTO): Promise<void> {
    this.records.set(`${record.userId}|${record.deviceId}`, { ...record });
  }

  async hasPushSubscription(userId: string, endpoint?: string | null): Promise<boolean> {
    if (endpoint) return this.subscriptions.has(`${userId}|${endpoint}`);
    for (const key of this.subscriptions) {
      if (key === userId || key.startsWith(`${userId}|`)) return true;
    }
    return false;
  }
}

/* ------------------------------------------------------------------ */
/* Gmail gate derivation (email_connections is the source of truth)    */
/* ------------------------------------------------------------------ */

export interface GmailGateView {
  state: GmailGateState;
  connectionRef: string | null;
  /** The actual Google-granted scope string on the connection row. */
  grantedScope: string | null;
  emailAddress: string | null;
  /** True once a sync/watch exists — reconciliation has initialized. */
  syncInitialized: boolean;
}

interface EmailConnectionGateRow {
  id: string;
  provider: string;
  connection_status: string;
  granted_scopes: string[] | null;
  email_address: string | null;
  last_synced_at: string | null;
}

export async function readGmailGateView(
  supabase: SupabaseClient,
  userId: string
): Promise<GmailGateView> {
  const { data, error } = await supabase
    .from("email_connections")
    .select("id, provider, connection_status, granted_scopes, email_address, last_synced_at")
    .eq("user_id", userId)
    .eq("provider", GMAIL_PROVIDER)
    .neq("connection_status", "disconnected")
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (error) throw new Error(`gmail connection lookup failed: ${error.message}`);
  if (!data) {
    return { state: "NOT_CONNECTED", connectionRef: null, grantedScope: null, emailAddress: null, syncInitialized: false };
  }
  const row = data as EmailConnectionGateRow;
  const scopes = Array.isArray(row.granted_scopes) ? row.granted_scopes : [];
  const grantedScope = scopes.length ? scopes.join(" ") : null;
  if (row.connection_status === "revoked") {
    return { state: "REVOKED", connectionRef: row.id, grantedScope, emailAddress: row.email_address, syncInitialized: false };
  }
  if (row.connection_status !== "connected" && row.connection_status !== "syncing") {
    return { state: "REAUTH_REQUIRED", connectionRef: row.id, grantedScope, emailAddress: row.email_address, syncInitialized: false };
  }
  if (!scopes.includes(GMAIL_READONLY_SCOPE)) {
    // Connected without the read scope the lane needs — the identity is
    // there but the granted scope does not cover reconciliation.
    return { state: "CONNECTED", connectionRef: row.id, grantedScope, emailAddress: row.email_address, syncInitialized: false };
  }
  const syncInitialized = Boolean(row.last_synced_at) || row.connection_status === "syncing";
  return {
    state: syncInitialized ? "RECONCILIATION_ARMED" : "CONNECTED",
    connectionRef: row.id,
    grantedScope,
    emailAddress: row.email_address,
    syncInitialized
  };
}

/** The connected Gmail address for the handoff emailed-link fallback. */
export async function connectedGmailAddress(
  supabase: SupabaseClient,
  userId: string
): Promise<string | null> {
  const view = await readGmailGateView(supabase, userId);
  return view.state === "CONNECTED" || view.state === "RECONCILIATION_ARMED" ? view.emailAddress : null;
}

/* ------------------------------------------------------------------ */
/* Evidence evaluation                                                 */
/* ------------------------------------------------------------------ */

export interface GateEvidence {
  /** Display-mode reading from the installed context (client platform state). */
  standaloneDetected: boolean;
  /** Notification.permission as read on the device. */
  notificationPermission: "granted" | "denied" | "default";
  /** The device's push subscription endpoint, when one exists. */
  pushEndpoint?: string | null;
}

export interface GateEvaluationInput {
  userId: string;
  deviceId: string;
  platform: "ios" | "android" | "other";
  evidence: GateEvidence;
  gmail: GmailGateView;
  now: UtcInstant;
}

/**
 * Compute (and validate) the authoritative gate record from platform
 * evidence. READY is reachable only with a detected install AND a
 * granted permission AND a server-verified push subscription.
 */
export async function evaluateGateEvidence(
  store: GateStore,
  input: GateEvaluationInput
): Promise<GateStateDTO> {
  const prior = await store.load(input.userId, input.deviceId);
  const { evidence } = input;

  let installDetectedAt: UtcInstant | null = prior?.installDetectedAt ?? null;
  let installState: InstallGateState;
  if (!evidence.standaloneDetected && !installDetectedAt) {
    installState = "NOT_INSTALLED";
  } else {
    if (!installDetectedAt) installDetectedAt = input.now;
    if (evidence.notificationPermission === "granted") {
      const subscribed = await store.hasPushSubscription(input.userId, evidence.pushEndpoint ?? null);
      // Granted at the OS prompt but no live subscription on file:
      // the alerts leg is not yet proven — stay at the ask.
      installState = subscribed ? "READY" : "NOTIFY_ASK";
    } else if (evidence.notificationPermission === "denied") {
      installState = "NOTIFY_DENIED";
    } else {
      installState = "NOTIFY_ASK";
    }
  }

  // Gmail fields refresh from the source of truth on every evaluation.
  // The Build 2 consent label is recorded in the gate row the first
  // time an armed connection is observed — before any lane reads mail
  // (Phase 8 consumes this record; the OAuth callback wrote the
  // connection, with its granted scope, before any sync ran).
  const gmailArmed = input.gmail.state === "RECONCILIATION_ARMED";
  const gmailConsentScope = gmailArmed
    ? GMAIL_CONSENT_SCOPE
    : (prior?.gmailConnectionRef === input.gmail.connectionRef ? prior?.gmailConsentScope ?? null : null);

  const record: GateStateDTO = {
    userId: input.userId,
    deviceId: input.deviceId,
    platform: input.platform,
    installState,
    alertsPermission: evidence.notificationPermission,
    alertsCheckedAt: input.now,
    installDetectedAt,
    gmailState: input.gmail.state,
    gmailConnectionRef: input.gmail.connectionRef,
    gmailConsentScope,
    flowAllowed: installState === "READY",
    updatedAt: input.now
  };

  const parsed = parseGateStateDTO(record);
  if (!parsed.ok) {
    throw new Error(`gate evaluation produced an invalid record: ${parsed.errors.join("; ")}`);
  }
  await store.save(record);
  return record;
}

/** A fresh (never-attested) record view for status reads. */
export function emptyGateRecord(input: {
  userId: string;
  deviceId: string;
  platform: "ios" | "android" | "other";
  gmail: GmailGateView;
  now: UtcInstant;
}): GateStateDTO {
  return {
    userId: input.userId,
    deviceId: input.deviceId,
    platform: input.platform,
    installState: "NOT_INSTALLED",
    alertsPermission: null,
    alertsCheckedAt: null,
    installDetectedAt: null,
    gmailState: input.gmail.state,
    gmailConnectionRef: input.gmail.connectionRef,
    gmailConsentScope: null,
    flowAllowed: false,
    updatedAt: input.now
  };
}

/* ------------------------------------------------------------------ */
/* Generation enforcement (beside the billing gate, Phase 6)           */
/* ------------------------------------------------------------------ */

export interface GateFlowContext {
  /** Which flow the generation request came from. Absent = legacy. */
  surface?: "mobile" | "desktop" | null;
  deviceId?: string | null;
}

export type GateEnforcementDecision =
  | { ok: true }
  | {
      ok: false;
      status: 403;
      error: "INSTALL_REQUIRED" | "ALERTS_REQUIRED";
      message: string;
    };

/**
 * The generate route consults this BEFORE any job is created. Rules:
 *  - Flag off → no gate (pre-Build-2 behavior, byte-for-byte).
 *  - Desktop flow → no gate at all (owner ruling 2026-10-21 18:54).
 *  - Mobile flow → a green (READY) attestation for (user, device) is
 *    required. No record, a red record, or a missing device id all
 *    refuse, naming whichever half is owed.
 */
export async function enforceGenerationGate(params: {
  store: GateStore | null;
  userId: string;
  context: GateFlowContext | null | undefined;
  env?: Record<string, string | undefined>;
}): Promise<GateEnforcementDecision> {
  if (!build2GatesEnabled(params.env)) return { ok: true };
  const surface = params.context?.surface ?? null;
  if (surface !== "mobile") return { ok: true }; // desktop + legacy: no gate

  const deviceId = (params.context?.deviceId || "").trim();
  const record = deviceId && params.store ? await params.store.load(params.userId, deviceId) : null;
  if (record && record.flowAllowed && record.installState === "READY") return { ok: true };

  const alertsOwed =
    record !== null &&
    (record.installState === "NOTIFY_ASK" ||
      record.installState === "NOTIFY_DENIED" ||
      record.installState === "GUIDED_ENABLE" ||
      record.installDetectedAt !== null);
  if (alertsOwed) {
    return { ok: false, status: 403, error: "ALERTS_REQUIRED", message: ALERTS_BLOCK_MESSAGE };
  }
  return { ok: false, status: 403, error: "INSTALL_REQUIRED", message: INSTALL_BLOCK_MESSAGE };
}
